// Parse the script JSON from OpenAI response
let scriptData;

try {
  const content = $input.first().json.message?.content || $input.first().json.content || $input.first().json.text;

  // Extract JSON from markdown code blocks if present
  const jsonMatch = content.match(/```json\s*([\s\S]*?)\s*```/) || content.match(/```\s*([\s\S]*?)\s*```/);
  const jsonString = jsonMatch ? jsonMatch[1] : content;

  scriptData = JSON.parse(jsonString.trim());
} catch (e) {
  throw new Error('Failed to parse script JSON: ' + e.message);
}

// Add metadata from previous nodes
const inputs = $('Extract Inputs').first().json;
scriptData.user_email = inputs.user_email;
scriptData.business_industry = inputs.business_industry;
scriptData.duration_seconds = inputs.duration_seconds;
scriptData.scene_count = inputs.scene_count;
scriptData.tone_style = inputs.tone_style;
scriptData.created_at = inputs.created_at;

// Validate scenes exist
if (!scriptData.scenes || scriptData.scenes.length === 0) {
  throw new Error('No scenes generated in script');
}

return { json: scriptData };

// Combine all narrations into smooth flowing script
const scenes = $input.first().json.scenes_with_images;
const scriptData = $('Parse Script JSON').first().json;

// Get narrations in order
const narrations = scenes
  .sort((a, b) => a.scene_number - b.scene_number)
  .map(s => s.narration)
  .join(' ');

// Use the full_narration if available, otherwise combine
const fullNarration = scriptData.full_narration || narrations;

return {
  json: {
    full_narration: fullNarration,
    scene_count: scenes.length,
    total_duration: scriptData.duration_seconds,
    scenes_with_images: scenes,
    story_title: scriptData.story_title,
    instagram_caption: scriptData.instagram_caption,
    hashtags: scriptData.hashtags,
    call_to_action: scriptData.call_to_action
  }
};

// Prepare data for Runway ML video generation
const combinedData = $('Combine Narration').first().json;
const voiceoverData = $input.first().json;

// Get scenes sorted by number
const scenes = combinedData.scenes_with_images.sort((a, b) => a.scene_number - b.scene_number);

// Prepare image sequence for Runway ML
const imageSequence = scenes.map(scene => ({
  image_url: scene.image_url,
  duration: scene.duration_seconds,
  scene_number: scene.scene_number,
  text_overlay: scene.text_overlay
}));

return {
  json: {
    image_sequence: imageSequence,
    total_duration: combinedData.total_duration,
    story_title: combinedData.story_title,
    instagram_caption: combinedData.instagram_caption,
    hashtags: combinedData.hashtags,
    call_to_action: combinedData.call_to_action,
    first_frame_url: imageSequence[0]?.image_url,
    voiceover_ready: true
  }
};

// Extract task ID from Runway response and prepare for async processing
const response = $input.first().json;
const taskId = response.body?.id || response.id;

if (!taskId) {
  throw new Error('Failed to start Runway ML task - no task ID returned');
}

// Get user info for response
const scriptData = $('Parse Script JSON').first().json;

return {
  json: {
    task_id: taskId,
    status: 'processing',
    user_email: scriptData.user_email,
    business_industry: scriptData.business_industry,
    story_title: scriptData.story_title || 'Your Doodle Reel'
  }
};
